package com.xiaomiscalesync.crypto

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Known-answer tests for [Hkdf] against fixtures generated by
 * `scripts/gen_vectors.py` (Python `cryptography` HKDF, RFC 5869),
 * including RFC 5869 Appendix A.1 Test Case 1.
 */
class HkdfTest {

    private val fixtures: List<VectorFixture.Hkdf> =
        Vectors.load("crypto_vectors").filterIsInstance<VectorFixture.Hkdf>()

    private fun fixture(name: String): VectorFixture.Hkdf = fixtures.first { it.name == name }

    @Test
    fun hkdfLoginProducesPinned64ByteOutput() {
        val f = fixture("hkdf_login")
        val out = Hkdf.sha256(f.ikm, f.salt, f.info, f.length)
        assertEquals(64, out.size)
        assertArrayEquals(f.output, out)
    }

    @Test
    fun hkdfLoginInfoIsExactlyMibleLoginInfo() {
        val f = fixture("hkdf_login")
        assertArrayEquals("mible-login-info".toByteArray(Charsets.US_ASCII), f.info)
    }

    @Test
    fun hkdfLoginOutputSplitsIntoPinnedSessionKeys() {
        val f = fixture("hkdf_login")
        val out = Hkdf.sha256(f.ikm, f.salt, f.info, f.length)
        // Session key layout: dev_key = out[0..16), app_key = out[16..32),
        // dev_iv = out[32..36), app_iv = out[36..40). Segments are pinned
        // independently of the fixture file.
        assertEquals("2a1118b18447fd06cc2296e154444b6a", out.copyOfRange(0, 16).toHex())
        assertEquals("805499e16fe1cd0373d3eb744709e9c0", out.copyOfRange(16, 32).toHex())
        assertEquals("d9203384", out.copyOfRange(32, 36).toHex())
        assertEquals("6909db69", out.copyOfRange(36, 40).toHex())
    }

    @Test
    fun rfc5869TestCase1ProducesPinnedOkm() {
        val f = fixture("hkdf_rfc5869_tc1")
        assertEquals(42, f.length)
        val out = Hkdf.sha256(f.ikm, f.salt, f.info, f.length)
        assertEquals(42, out.size)
        assertEquals(
            "3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf" +
                "34007208d5b887185865",
            out.toHex(),
        )
    }

    @Test
    fun expandOutputIsPrefixConsistentAcrossRequestedLengths() {
        val f = fixture("hkdf_login")
        val out64 = Hkdf.sha256(f.ikm, f.salt, f.info, 64)
        val out32 = Hkdf.sha256(f.ikm, f.salt, f.info, 32)
        val out40 = Hkdf.sha256(f.ikm, f.salt, f.info, 40)
        assertEquals(32, out32.size)
        assertEquals(40, out40.size)
        assertArrayEquals(out64.copyOfRange(0, 32), out32)
        assertArrayEquals(out64.copyOfRange(0, 40), out40)
    }

    private fun ByteArray.toHex(): String =
        joinToString("") { "%02x".format(it.toInt() and 0xFF) }
}
